uint IPv4(string text) {
    byte[] bytes = System.Net.IPAddress.Parse(text).GetAddressBytes();
    if (bytes.Length != 4) throw new ArgumentException("IPv4 only");
    return System.Buffers.Binary.BinaryPrimitives.ReadUInt32BigEndian(bytes);
}
uint Mask(int n) => n switch {
    0 => 0, >= 1 and <= 32 => uint.MaxValue << (32 - n),
    _ => throw new ArgumentOutOfRangeException(nameof(n))
};
bool Match(uint ip, uint network, int n) => (ip & Mask(n)) == network;
// Route is an original lab record, not a Windows routing API.
var selected = routes.Where(r => Match(IPv4(destination), IPv4(r.Network), r.Prefix))
    .OrderByDescending(r => r.Prefix).ThenBy(r => r.Metric).First();
